import {SCHEMA,uid,clone,createProject,createSection,createFlow,groupScore,combinedScore,rows,priorityRows,csvExport,validateProject} from './core.js';
import {exampleProject} from './examples.js';

function openDialog(title,body,onSubmit,{submit,extra=''}={}){
 const dialog=$('#dialog');if(dialog.open)dialog.close();
 dialog.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button type="button" data-modal-cancel class="quiet icon-only" aria-label="${t('Close','关闭')}">${icon('close')}</button></div><form id="dialog-form"><div class="dialog-body">${body}<div class="dialog-actions">${extra}<span class="spacer"></span><button type="button" data-modal-cancel>${t('Cancel','取消')}</button>${onSubmit?`<button type="submit" class="primary">${esc(submit||t('Save','保存'))}</button>`:''}</div></div></form>`;
 dialog.querySelectorAll('[data-modal-cancel]').forEach(b=>b.onclick=()=>dialog.close());
 dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(onSubmit){const result=onSubmit(data);if(result!==false)dialog.close();}};
 dialog.showModal();
}
function modalField(label,name,value='',{type='text',textarea=false,required=false,min=0,max=1e9,options=null}={}){return `<label class="field">${esc(label)}${options?`<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select>`:textarea?`<textarea name="${name}" ${required?'required':''} maxlength="20000">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?`min="${min}" max="${max}" step="any"`:''} maxlength="${name==='label'||name==='labelZh'?160:500}">`}</label>`;}
function confirmDialog(title,message,fn){openDialog(title,`<p>${esc(message)}</p><p>${t('Download a JSON copy first if you want to keep the current version. Undo is also available during this session.','如需保留当前版本，请先下载 JSON。当前会话也支持撤销。')}</p>`,()=>fn(),{submit:t('Continue','继续'),extra:btn('export',t('Save JSON first','先保存 JSON'),'download','small')});}
function editSection(id=sectionId){
 const s=project.sections.find(s=>s.id===id);if(!s)return;
 openDialog(t('Edit sub-section','编辑子区段'),modalField(t('Sub-section name','子区段名称'),'label',s.label,{required:true})+modalField(t('Overall sub-section notes','子区段整体记录'),'summary',s.summary,{textarea:true})+`<p>${t('Patient flows in this sub-section','本子区段中的患者分流')}</p><div class="row wrap">${s.flows.map(f=>btn('edit-flow',esc(f.label),'edit','small',`data-id="${f.id}" data-section="${s.id}"`)).join('')}${btn('add-flow',t('Add flow','添加分流'),'plus','small',`data-id="${s.id}"`)}</div>`,data=>mutate(()=>{s.label=data.label;s.summary=data.summary;}),{extra:project.sections.length>1?btn('delete-section',t('Delete','删除'),'trash','small danger',`data-id="${s.id}"`):''});
}
function editFlow(fid=flowId,sid=sectionId){
 const s=project.sections.find(s=>s.id===sid),f=s?.flows.find(f=>f.id===fid);if(!f)return;
 openDialog(t('Patient flow details','患者分流资料'),`<p>${esc(s.label)}</p>`+modalField(t('Flow label / characteristics','分流名称与特征'),'label',f.label,{required:true})+modalField(t('Patient volume (blank = unknown)','患者人数（空白表示未知）'),'volume',f.volume??'',{type:'number'})+modalField(t('Evidence source / scope','证据来源与范围'),'source',f.source,{textarea:true}),data=>mutate(()=>{f.label=data.label;f.volume=data.volume===''?null:Number(data.volume);f.source=data.source;}),{extra:s.flows.length>1?btn('delete-flow',t('Delete flow','删除分流'),'trash','small danger',`data-id="${f.id}" data-section="${s.id}"`):''});
}
function nodeDialog(id){
 selectedNode=id;const n=project.nodes.find(n=>n.id===id);if(!n)return;
 const connections=project.edges.filter(e=>e.from===id||e.to===id);
 openDialog(t('Pathway node','路径节点'),modalField(t('Node label','节点文字'),'label',n.label,{required:true})+modalField(t('Shape','节点形状'),'kind',n.kind,{options:[['process',t('Step','步骤')],['decision',t('Decision','决策')],['terminal',t('Start / end','开始或结束')]]})+modalField(t('Sub-section','所属子区段'),'sectionId',n.sectionId,{options:project.sections.map((s,i)=>[s.id,`S-${i+1} · ${s.label}`])})+modalField(t('Link to patient flow (optional)','关联患者分流（可选）'),'flowId',n.flowId||'',{options:[['',t('Sub-section only','仅关联子区段')],...project.sections.flatMap(s=>s.flows.map(f=>[f.id,s.label+' · '+f.label]))]})+`<div class="form-grid">${modalField('X','x',n.x,{type:'number',max:10000})}${modalField('Y','y',n.y,{type:'number',max:20000})}</div>${connections.length?`<p>${t('Connections · select to edit','连接 · 点击修改')}</p><div class="row wrap">${connections.map(e=>btn('edit-edge',esc(e.label||t('Unlabelled connection','未命名连接')),'edit','small',`data-id="${e.id}"`)).join('')}</div>`:''}`,data=>{if(data.flowId&&!project.sections.find(s=>s.id===data.sectionId).flows.some(f=>f.id===data.flowId)){toast(t('Choose a patient flow belonging to the selected sub-section.','请选择属于所选子区段的患者分流。'));return false;}mutate(()=>Object.assign(n,{label:data.label,kind:data.kind,sectionId:data.sectionId,flowId:data.flowId,x:Number(data.x),y:Number(data.y)}));},{extra:btn('delete-node',t('Delete node','删除节点'),'trash','small danger',`data-id="${id}"`)});
}
function edgeDialog(id=null){
 if(project.nodes.length<2){toast(t('Add at least two nodes before connecting them.','至少需要两个节点才能建立连接。'));return;}
 const e=project.edges.find(e=>e.id===id),options=project.nodes.map(n=>[n.id,n.label]);
 openDialog(t(e?'Edit connection':'Connect pathway nodes',e?'编辑连接':'连接路径节点'),modalField(t('From','起点'),'from',e?.from||selectedNode||project.nodes[0].id,{options})+modalField(t('To','终点'),'to',e?.to||project.nodes[1].id,{options})+modalField(t('Branch / decision label','分支或决策标签'),'label',e?.label||''),data=>{if(data.from===data.to){toast(t('Choose two different nodes.','请选择两个不同的节点。'));return false;}if(project.edges.some(other=>other.id!==id&&other.from===data.from&&other.to===data.to)){toast(t('These nodes are already connected. Edit the existing connection.','这两个节点已连接，请编辑现有连接。'));return false;}mutate(()=>{if(e)Object.assign(e,data);else project.edges.push({id:uid('edge'),...data});});},{extra:e?btn('delete-edge',t('Delete connection','删除连接'),'trash','small danger',`data-id="${e.id}"`):''});
}
function discussionDialog(id=null){const f=activeFlow(),a=f.discussion.find(a=>a.id===id);openDialog(t(a?'Edit discussion note':'Add to the conversation',a?'编辑讨论记录':'添加讨论记录'),modalField(t('Question, agreement or proposed change','问题、共识或拟议改进'),'text',a?.text||'',{textarea:true,required:true})+modalField(t('Perspective / owner','视角或负责人'),'owner',a?.owner||'')+modalField(t('Status','状态'),'status',a?.status||'open',{options:[['open',t('Open question','待讨论')],['agreed',t('Agreed','已达成共识')],['testing',t('Testing','测试中')],['done',t('Done','已完成')]]}),data=>mutate(()=>{if(a)Object.assign(a,data);else f.discussion.push({id:uid('note'),...data});}));}
function helpDialog(){openDialog(t('A shared conversation, step by step','逐步展开共同讨论'),`<div class="help-steps">${[[t('Agree on a purpose','明确共同目标'),t('Describe the healthcare service, the people involved and the improvement you want to explore.','明确服务范围、参与角色，以及希望探索的改进。')],[t('Build the measures together','共同确定评价方式'),t('Discuss dimensions, evidence, weights and what 1–10 means before assigning grades. Use 0 weight for context-only measures.','先讨论维度、证据、权重与 1–10 分的含义。参照性指标可设为 0 权重。')],[t('Map & bring in evidence','绘制路径，汇集证据'),t('Group steps into sub-sections, identify patient flows and place observations, quotes and operational data side by side.','划分子区段与患者分流，将观察、引语与运作数据放在一起。')],[t('Discuss & try a change','讨论并尝试改进'),t('Compare complete grades, return to the evidence and record questions, agreements and next steps.','比较完整评分，回到证据，记录问题、共识与下一步。')]].map(([h,p])=>`<div class="help-step"><h3>${h}</h3><p>${p}</p></div>`).join('')}</div><p style="margin-top:18px">${t('Editing the map: enable Edit map, drag nodes to move them, select a node to edit it, and use Connect to add a labelled branch. Flow selection controls the evidence in both side panels.','编辑路径：打开“编辑路径”，拖动节点，点击节点修改文字或所属区段，使用“连接”添加带标签的分支。分流选择控制左右两侧展示的同一份证据。')}</p><p>${t('The workspace saves on this device. Save JSON for a portable backup and exchange it with collaborators. This version has no simultaneous multi-user editing. Enter anonymized research material only.','工作区保存在当前设备。保存 JSON 可进行备份或与协作者交换文件。此版本不支持多人实时同步。请仅填写去标识化的研究材料。')}</p>`,null);}
function aboutDialog(){openDialog(t('About this tool','关于这个工具'),`<div class="about-text"><p><strong>Pathway Redesign</strong> ${t('is a web adaptation of the dialogic tool developed in Peng Lu’s master’s thesis in Product–Service System Design, supervised by Daniela Sangiorgi.','改编自 Peng Lu 在 Daniela Sangiorgi 指导下完成的产品服务系统设计硕士论文中的对话工具。')}</p><p><em>Acknowledging the Voice of Service Design(ers) in Healthcare and Vice Versa: Exploring a Dialogic Tool as a Boundary Object for Patient Experience Improvement.</em> Academic year 2021/2022.</p><h3>${t('What is carried forward','延续的结构')}</h3><p>${t('The shared pathway, sub-sections and patient flows link experience design evidence with clinical and managerial evidence. The tool supports cross-disciplinary communication; its dimensions, criteria and weights are open to negotiation.','以共同路径、子区段和患者分流连接体验设计证据与临床管理证据，促进跨专业交流。维度、评价标准和权重均可共同讨论。')}</p><h3>${t('What this web version changes','网页版的调整')}</h3><p>${t('Editable graph nodes and branches, linked evidence panels, configurable dimensions, explicit missing data, local saving and file exchange. Graph drag-and-drop, discussion records and the interface are new implementation choices. The original thesis supports a timeline-to-flowchart development; this version implements the later flowchart approach.','可编辑节点与分支、联动证据面板、可配置维度、明确的缺失数据、本地保存与文件交换。拖动、讨论记录和界面是本次实现新增的方式。原论文经历了从时间线到流程图的迭代，本版本采用后期流程图结构。')}</p><h3>${t('Transparent calculation','明确的计算规则')}</h3><p>${t('Each side uses the weighted average of active grades. The example’s experience weights 3, 4, 5 and 2 sum to 14; its first grades 4, 5, 6 and 4 give 5.00, correcting the source workbook’s mismatched denominator. The example’s managerial weights sum to 17; target time has weight 0. Both the original sum (/20) and the thesis-proposed weighted balance (/10) are available.','每侧采用有效评分的加权平均。示例体验权重 3、4、5、2 合计为 14，首组评分 4、5、6、4 得到 5.00，修正原表格分母不一致的问题。示例管理侧权重合计为 17，目标时间权重为 0。可选择原版相加（满分 20）或论文提出的两侧加权平衡（满分 10）。')}</p><h3>${t('Example provenance & limits','示例来源与边界')}</h3><p>${t('S-1 and S-2 use illustrative values from the supplied example workbook. Other scores stay blank. The map is a simplified reconstruction of thesis Figure 46, adapted there from Schertler et al. (2007), DOI 10.1007/s00330-007-0724-9. It is not a current care protocol or a clinical decision aid.','S-1 与 S-2 使用所提供示例表格中的演示值，其他分数留空。路径图简化重建自论文图 46；该图源于 Schertler 等人（2007），DOI 10.1007/s00330-007-0724-9。此图不作为现行诊疗规程或临床决策依据。')}</p><p>${t('The thesis’s proposed shared-learning process is a future direction, rather than a validated outcome. This web adaptation has not been evaluated with healthcare teams.','论文提出的共同学习过程属于未来方向，不能视为已验证的成果。本网页版尚未经过医护团队的使用评估。')}</p><p>© Peng Lu · ${t('No source photographs or third-party sticker artwork are redistributed.','不附带原材料中的照片或第三方贴纸图案。')}</p></div>`,null);}
function exportsDialog(){openDialog(t('Take the conversation with you','导出当前工作'),`<p>${t('JSON keeps the entire editable project, including the map, evidence, weights and discussion records. CSV is a table for analysis; it cannot restore a project. SVG exports the map. Print includes the map, criteria and evidence.','JSON 保留完整可编辑项目，包括路径、证据、权重和讨论记录。CSV 为分析用表格，无法恢复项目。SVG 导出路径图。打印报告包含路径、评价依据与证据。')}</p><div class="stack">${btn('export',t('Save editable project · JSON','保存可编辑项目 · JSON'),'download')}${btn('csv',t('Evidence table · CSV','证据表格 · CSV'),'table')}${btn('svg',t('Pathway diagram · SVG','路径图 · SVG'),'map')}${btn('print',t('Print report / save as PDF','打印报告或另存 PDF'),'print')}</div>`,null);}
function printReport(){
 const report=$('#print-report');report.innerHTML=`<h1>${esc(project.title)}</h1><p>${esc(project.goal)}</p><p class="print-note">${esc(project.period)} · ${esc(project.team)} · ${t('Total volume','患者总人数')}: ${project.volume??'—'}</p><p>${esc(project.context)}</p><p class="print-note">${t('Pathway Redesign · Peng Lu · Local project report','Pathway Redesign · Peng Lu · 本地项目报告')} · ${new Date().toLocaleDateString(language==='zh'?'zh-CN':'en-GB')} · ${project.settings.combination==='sum'?t('Sum /20','相加 /20'):t('Weighted balance /10','加权平衡 /10')}</p>${graphSvg(true).replace('id="pathway-svg"','class="print-graph"')}<div class="print-section"><h2>${t('Shared measures & grading criteria','共同指标与评分依据')}</h2><p>${t('Higher grades mean better performance. Missing active grades prevent ranking. Side grades are weighted averages.','分数越高表示表现越好。启用评分缺失的分流不参与排序。单侧分数为加权平均。')}</p><p>${esc(project.settings.weightRationale)}</p><p>${t('Combination','合成方式')}: ${project.settings.combination==='sum'?t('Experience + managerial /20','体验分 + 管理分 /20'):`(${project.settings.experienceWeight} × E + ${project.settings.managementWeight} × M) / ${project.settings.experienceWeight+project.settings.managementWeight}`}.</p><table><thead><tr><th>${t('Perspective','视角')}</th><th>${t('Dimension','维度')}</th><th>${t('Weight','权重')}</th><th>${t('Grading criteria','评分依据')}</th></tr></thead><tbody>${project.dimensions.map(d=>`<tr><td>${esc(d.side)}</td><td>${esc(dlabel(d))}</td><td>${d.weight}</td><td>${esc(d.rubric)}</td></tr>`).join('')}</tbody></table></div>${project.sections.map((s,i)=>`<section class="print-section"><h2>S-${i+1} · ${esc(s.label)}</h2><p>${esc(s.summary)}</p>${s.flows.map(f=>`<h3>${esc(f.label)} · ${t('Patient volume','患者人数')}: ${f.volume??'—'} · ${t('Combined grade','综合分')}: ${fmt(combinedScore(project,f))}/${maxGrade()}</h3><p>${esc(f.insight)}</p><table><thead><tr><th>${t('Dimension / weight','维度与权重')}</th><th>${t('Observed value','观察值')}</th><th>${t('Grade /10','评分 /10')}</th><th>${t('Evidence / reason','证据与理由')}</th></tr></thead><tbody>${project.dimensions.map(d=>{const v=f.values[d.id]||{};return `<tr><td>${esc(dlabel(d))} · w ${d.weight}</td><td>${esc(v.value)} ${esc(d.unit)}</td><td>${fmt(v.score)}</td><td>${esc(v.note)}</td></tr>`;}).join('')}</tbody></table><p>${t('Experience notes','体验记录')}: ${esc(f.experienceNotes)}<br>${t('Managerial notes','管理记录')}: ${esc(f.managementNotes)}<br>${t('Source','来源')}: ${esc(f.source)}</p>${f.discussion.map(a=>`<p>[${esc(a.status)}] ${esc(a.text)} · ${esc(a.owner)}</p>`).join('')}`).join('')}</section>`).join('')}`;
 $('#dialog').close();window.print();
}
function runAction(action,el){
 const id=el?.dataset.id;
 switch(action){
  case 'export':download(slug()+'.json',JSON.stringify({...project,updatedAt:new Date().toISOString()},null,2),'application/json');toast(t('Editable project downloaded.','已下载可编辑项目。'));break;
  case 'import':$('#import-file').click();break;
  case 'csv':download(slug()+'-evidence.csv',csvExport(project),'text/csv;charset=utf-8');break;
  case 'svg':download(slug()+'-pathway.svg','<?xml version="1.0" encoding="UTF-8"?>\n'+graphSvg(true),'image/svg+xml');break;
  case 'print':printReport();break;
  case 'exports':exportsDialog();break;
  case 'help':helpDialog();break;
  case 'about':aboutDialog();break;
  case 'language':language=language==='en'?'zh':'en';try{localStorage.setItem(STORE+'-language',language);}catch(e){}renderApp();break;
  case 'undo':if(history.length){future.push(clone(project));project=history.pop();save();renderApp();}break;
  case 'redo':if(future.length){history.push(clone(project));project=future.pop();save();renderApp();}break;
  case 'new':confirmDialog(t('Start a new pathway?','开始新路径？'),t('A blank project will replace the current workspace on this device.','空白项目会替换此设备上的当前工作区。'),()=>mutate(()=>{project=createProject();sectionId=project.sections[0].id;flowId=activeSection().flows[0].id;view='settings';editGraph=false;}));break;
  case 'example':confirmDialog(t('Load the thesis example?','加载论文示例？'),t('The example will replace the current workspace.','示例会替换当前工作区。'),()=>mutate(()=>{project=exampleProject();sectionId=project.sections[0].id;flowId=activeSection().flows[0].id;view='workspace';editGraph=false;}));break;
  case 'project-settings':case 'scoring-settings':view='settings';renderApp();if(action==='scoring-settings')$('#scoring-settings')?.scrollIntoView({behavior:'smooth'});break;
  case 'go-priorities':view='priorities';renderApp();break;
  case 'edit-section':editSection(id||sectionId);break;
  case 'edit-flow':editFlow(id||flowId,el?.dataset.section||sectionId);break;
  case 'add-section':openDialog(t('Add sub-section','添加子区段'),modalField(t('Sub-section name','子区段名称'),'label','',{required:true}),data=>mutate(()=>{if(project.sections.length>=100){toast('Limit: 100 sub-sections.');return;}const s=createSection(data.label);project.sections.push(s);sectionId=s.id;flowId=s.flows[0].id;const y=project.nodes.length?Math.max(...project.nodes.map(n=>n.y))+150:70;project.nodes.push({id:uid('node'),sectionId:s.id,label:data.label,kind:'process',x:300,y:Math.min(y,20000)});}));break;
  case 'add-flow':openDialog(t('Add patient flow','添加患者分流'),modalField(t('Sub-section','子区段'),'section',id||sectionId,{options:project.sections.map(s=>[s.id,s.label])})+modalField(t('Flow label','分流名称'),'label',t('New patient flow','新患者分流'),{required:true}),data=>mutate(()=>{const s=project.sections.find(s=>s.id===data.section);if(s.flows.length>=50){toast('Limit: 50 flows per sub-section.');return;}const f=createFlow(data.label);s.flows.push(f);sectionId=s.id;flowId=f.id;}));break;
  case 'section-up':case 'section-down':mutate(()=>{const i=project.sections.findIndex(s=>s.id===id),j=i+(action==='section-up'?-1:1);if(j>=0&&j<project.sections.length)[project.sections[i],project.sections[j]]=[project.sections[j],project.sections[i]];});break;
  case 'delete-section':confirmDialog(t('Delete this sub-section?','删除此子区段？'),t('Its flows, evidence, map nodes and related connections will be removed.','将删除此区段的所有分流、证据、路径节点及相关连接。'),()=>mutate(()=>{const ns=new Set(project.nodes.filter(n=>n.sectionId===id).map(n=>n.id));project.sections=project.sections.filter(s=>s.id!==id);project.nodes=project.nodes.filter(n=>!ns.has(n.id));project.edges=project.edges.filter(e=>!ns.has(e.from)&&!ns.has(e.to));}));break;
  case 'delete-flow':confirmDialog(t('Delete this flow?','删除此分流？'),t('All evidence and discussion notes for this flow will be removed.','将删除此分流的证据与讨论记录。'),()=>mutate(()=>{const s=project.sections.find(s=>s.id===(el.dataset.section||sectionId));s.flows=s.flows.filter(f=>f.id!==id);project.nodes.filter(n=>n.flowId===id).forEach(n=>delete n.flowId);}));break;
  case 'toggle-graph':editGraph=!editGraph;renderApp();break;
  case 'add-node':openDialog(t('Add pathway node','添加路径节点'),modalField(t('Node label','节点文字'),'label','',{required:true})+modalField(t('Sub-section','子区段'),'sectionId',sectionId,{options:project.sections.map(s=>[s.id,s.label])})+modalField(t('Shape','节点形状'),'kind','process',{options:[['process',t('Step','步骤')],['decision',t('Decision','决策')],['terminal',t('Start / end','开始或结束')]]}),data=>mutate(()=>{if(project.nodes.length>=300){toast('Limit: 300 nodes.');return;}const y=Math.min(20000,Math.max(60,...project.nodes.filter(n=>n.sectionId===data.sectionId).map(n=>n.y))+100);project.nodes.push({id:uid('node'),...data,x:300,y});}));break;
  case 'add-edge':if(project.edges.length>=600){toast('Limit: 600 connections.');return;}edgeDialog();break;
  case 'edit-edge':edgeDialog(id);break;
  case 'delete-edge':mutate(()=>{project.edges=project.edges.filter(e=>e.id!==id);});$('#dialog').close();break;
  case 'delete-node':confirmDialog(t('Delete this node?','删除此节点？'),t('The node and its connections will be removed. The sub-section evidence stays.','将删除节点及其连接，保留区段证据。'),()=>mutate(()=>{project.nodes=project.nodes.filter(n=>n.id!==id);project.edges=project.edges.filter(e=>e.from!==id&&e.to!==id);}));break;
  case 'add-dimension':openDialog(t('Add a shared measure','添加共同指标'),modalField(t('Dimension name','维度名称'),'label','',{required:true})+modalField(t('Chinese label (optional)','中文名称（可选）'),'labelZh','')+modalField(t('Perspective','视角'),'side',el.dataset.side,{options:[['experience',t('Experience design','体验设计')],['management',t('Clinical & managerial','临床与管理')]]})+modalField(t('Weight','权重'),'weight',1,{type:'number',max:100})+modalField(t('Grading criteria','评分依据'),'rubric',t('1 = weakest; 10 = strongest. Agree on local criteria.','1 = 最弱，10 = 最佳。请共同确定具体标准。'),{textarea:true}),data=>mutate(()=>{if(project.dimensions.length>=40){toast('Limit: 40 dimensions.');return;}project.dimensions.push({id:uid('dimension'),...data,weight:Number(data.weight),kind:'text',unit:''});}));break;
  case 'delete-dimension':if(project.dimensions.length<=1){toast(t('Keep at least one dimension.','至少保留一个维度。'));break;}confirmDialog(t('Remove this dimension?','移除此维度？'),t('Its evidence and grades will be removed from all flows.','将从所有分流中删除此维度的证据与评分。'),()=>mutate(()=>{project.dimensions=project.dimensions.filter(d=>d.id!==id);rows(project).forEach(r=>delete r.flow.values[id]);}));break;
  case 'add-discussion':discussionDialog();break;
  case 'edit-discussion':discussionDialog(id);break;
  case 'delete-discussion':confirmDialog(t('Delete this note?','删除此记录？'),t('This discussion record will be removed.','将删除这条讨论记录。'),()=>mutate(()=>{activeFlow().discussion=activeFlow().discussion.filter(a=>a.id!==id);}));break;
 }
}
function bindGraph(){
 const svg=$('#pathway-svg');if(!svg)return;
 const activate=el=>{if(el.dataset.node){const n=project.nodes.find(n=>n.id===el.dataset.node);if(editGraph)nodeDialog(n.id);else{const scroller=$('#graph-scroll'),x=scroller.scrollLeft,y=scroller.scrollTop,previousSection=sectionId;sectionId=n.sectionId;flowId=n.flowId||(previousSection===sectionId?flowId:activeSection().flows[0].id);renderApp();$('#graph-scroll').scrollTo(x,y);}}else if(el.dataset.edge&&editGraph)edgeDialog(el.dataset.edge);};
 svg.addEventListener('keydown',e=>{const el=e.target.closest('[data-node],[data-edge]');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();activate(el);}});
 svg.addEventListener('click',e=>{if(!editGraph){const el=e.target.closest('[data-node]');if(el)activate(el);}else{const el=e.target.closest('[data-edge]');if(el)activate(el);}});
 if(!editGraph)return;
 svg.addEventListener('pointerdown',e=>{
  if(e.button!==0)return;const el=e.target.closest('[data-node]');if(!el)return;
  e.preventDefault();const n=project.nodes.find(n=>n.id===el.dataset.node),startX=e.clientX,startY=e.clientY,oldX=n.x,oldY=n.y,b=graphBounds(),ratio=b.width/svg.getBoundingClientRect().width;let x=oldX,y=oldY,moved=false;
  el.setPointerCapture(e.pointerId);
  const move=ev=>{const dx=(ev.clientX-startX)*ratio,dy=(ev.clientY-startY)*ratio;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;x=Math.max(10,Math.min(10000,oldX+dx));y=Math.max(30,Math.min(20000,oldY+dy));el.setAttribute('transform',`translate(${x} ${y})`);};
  const finish=ev=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',finish);el.removeEventListener('pointercancel',cancel);if(el.hasPointerCapture(ev.pointerId))el.releasePointerCapture(ev.pointerId);if(moved){const scroller=$('#graph-scroll'),sx=scroller.scrollLeft,sy=scroller.scrollTop;mutate(()=>{n.x=Math.round(x);n.y=Math.round(y);});$('#graph-scroll').scrollTo(sx,sy);}else activate(el);};
  const cancel=ev=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',finish);el.removeEventListener('pointercancel',cancel);el.setAttribute('transform',`translate(${oldX} ${oldY})`);};
  el.addEventListener('pointermove',move);el.addEventListener('pointerup',finish);el.addEventListener('pointercancel',cancel);
 });
}
function setField(path,value){
 const parts=path.split('.');let target;
 if(parts[0]==='flow'){target=activeFlow();parts.shift();if(parts[0]==='values'){target.values[parts[1]]??={value:'',score:null,note:''};}}
 else if(parts[0]==='project'){target=project;parts.shift();}
 else if(parts[0]==='settings'){target=project.settings;parts.shift();}
 else if(parts[0]==='dimension'){target=project.dimensions.find(d=>d.id===parts[1]);parts.splice(0,2);}
 if(!target)return;while(parts.length>1){target=target[parts.shift()];}target[parts[0]]=value;
}
function start(){
 document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){runAction(action.dataset.action,action);return;}const tab=e.target.closest('[data-view]');if(tab){view=tab.dataset.view;renderApp();return;}const toggle=e.target.closest('[data-dimension-toggle]');if(toggle){const id=toggle.dataset.dimensionToggle;if(expanded.has(id))expanded.delete(id);else expanded.add(id);const x=$('#graph-scroll')?.scrollLeft,y=$('#graph-scroll')?.scrollTop;renderApp();$('#graph-scroll')?.scrollTo(x||0,y||0);return;}const selectButton=e.target.closest('[data-select-section]');if(selectButton){view='workspace';select(selectButton.dataset.selectSection,selectButton.dataset.selectFlow);window.scrollTo(0,0);}});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.closest('input,textarea,select,[contenteditable]')&&!$('#dialog').open){e.preventDefault();runAction(e.shiftKey?'redo':'undo');}});
 $('#app').addEventListener('focusout',()=>{inputSession=null;});
 $('#app').addEventListener('input',e=>{
  if(e.target.id==='zoom'){zoom=Number(e.target.value);const svg=$('#pathway-svg'),b=graphBounds();svg.setAttribute('width',b.width*zoom/100);svg.setAttribute('height',b.height*zoom/100);$('#zoom-label').textContent=zoom+'%';return;}
  const path=e.target.dataset.field;if(!path)return;let value=e.target.value;
  if(e.target.type==='number'){
   e.target.setCustomValidity('');
   if(value===''){value=null;}else{value=Number(value);if(!Number.isFinite(value))return;const min=Number(e.target.min),max=Number(e.target.max);if(value<min||value>max){e.target.setCustomValidity(t(`Use a number between ${min} and ${max}.`,`请输入 ${min} 至 ${max} 之间的数字。`));e.target.reportValidity();return;}e.target.setCustomValidity('');}
   // All raw observations remain strings; only grades, weights and counts are numeric.
   if(path.endsWith('.value'))value=value===null?'':String(value);
   if((path.endsWith('.weight')||path.startsWith('settings.'))&&value===null)value=0;
  }
  const record=inputSession!==e.target;if(record)inputSession=e.target;
  mutate(()=>setField(path,value),{render:false,record});
 });
 $('#app').addEventListener('change',e=>{
  if(e.target.id==='section-select'){select(e.target.value);return;}
  if(e.target.id==='flow-select'){flowId=e.target.value;renderApp();return;}
  if(e.target.dataset.discussionStatus){mutate(()=>{activeFlow().discussion.find(a=>a.id===e.target.dataset.discussionStatus).status=e.target.value;});return;}
  const path=e.target.dataset.field;if(path&&(e.target.tagName==='SELECT')){mutate(()=>setField(path,e.target.value));return;}
  if(path&&e.target.validity&&!e.target.validity.valid){const parts=path.split('.');let value;if(parts[0]==='flow'){value=activeFlow();parts.shift();}else if(parts[0]==='project'){value=project;parts.shift();}else if(parts[0]==='settings'){value=project.settings;parts.shift();}else if(parts[0]==='dimension'){value=project.dimensions.find(d=>d.id===parts[1]);parts.splice(0,2);}for(const part of parts)value=value?.[part];e.target.value=value??'';e.target.setCustomValidity('');toast(t('The invalid entry was not saved. The previous value has been restored.','无效输入未保存，已恢复原值。'));}
 });
 $('#import-file').addEventListener('change',async e=>{
  const file=e.target.files[0];if(!file)return;e.target.value='';
  if(file.size>15*1024*1024){toast(t('Please use a project file smaller than 15 MB.','项目文件需小于 15 MB。'));return;}
  try{const imported=validateProject(JSON.parse(await file.text()));confirmDialog(t('Open this project?','打开此项目？'),`${imported.title} · ${imported.sections.length} ${t('sub-sections. This will replace the current workspace.','个子区段。此操作会替换当前工作区。')}`,()=>mutate(()=>{project=imported;sectionId=project.sections[0].id;flowId=activeSection().flows[0].id;view='workspace';editGraph=false;loadWarning='';}));}catch(error){toast(t('Cannot open project: ','无法打开项目：')+error.message);}
 });
 window.addEventListener('beforeunload',()=>{if(saveTimer){clearTimeout(saveTimer);try{localStorage.setItem(STORE,JSON.stringify(project));}catch(e){}}});
 renderApp();
}
